challenge.solution:
글자표 = "가나다라마바사아자차카타파하"
풀기 = {}
for i in range(len(글자표)):
    풀기[글자표[i]] = 글자표[i - 1]
암호 = input("암호: ")
편지 = ""
for 글자 in 암호:
    if 글자 in 풀기:
        편지 += 풀기[글자]
    else:
        편지 += 글자
print(편지)
